{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C04"],
      "claim": "Isradipine, a lipophilic dihydropyridine, had systemic availability of only 17% in healthy volunteers after oral administration, below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Pentazocine, a lipophilic small molecule subject to first-pass metabolism, had an oral bioavailability of 0.18 in normal subjects, below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C35"],
      "claim": "Isradipine showed mean systemic availability of 16.5% in healthy volunteers, supporting low oral bioavailability for lipophilic, extensively metabolized compounds.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Nifedipine had oral bioavailability of about 45% in humans, above the 20% threshold, but this reflects a smaller, less lipophilic dihydropyridine and is not structurally transferable to the polyisoprenyl quinone query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C24"],
      "claim": "A pyrazolopyrimidinone drug showed 34% oral bioavailability in healthy volunteers, above the threshold, but the structure is unrelated to the query's long-chain quinone.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "low",
  "decision_summary": "The query is a large, highly lipophilic polyisoprenyl ubiquinone; no direct record is available, and the weakly transferable low-F analogs (isradipine, pentazocine) are more consistent with poor oral bioavailability below 20%.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule.",
    "No structurally close analog with a polyisoprenyl quinone core in the evidence set.",
    "Formulation-dependent absorption data for highly lipophilic quinones are absent."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

